{"content":"#!/usr/bin/env python3
"""
Reparador de caminhos das KBs — v3 (escrita textual, sem yaml.dump).

Por que v3: `yaml.dump` RE-QUEBRA o caminho na saida (o dumper decide a
quebra de linha, e com `width=4096` ele ainda assimdivide linhas muito
longas em多点). Round-trip: parse -> fix -> dump -> parse volta a truncar.
Solucao: editar o arquivo YAML em TEXTO (regex sobre o bloco da entrada),
preservando o resto do arquivo byte a byte.
"""
import glob
import os
import re
import unicodedata
from collections import defaultdict
from pathlib import Path

import yaml

ROOT = Path("/home/study-agent")
BIB = ROOT / "data/biblioteca"
GLOBAL = BIB / "global"
STOP = {"de", "da", "do", "the", "a", "o", "and", "e", "of", "para", "com"}


def norm(s):
    s = unicodedata.normalize("NFKD", str(s))
    s = "".join(c for c in s if not unicodedata.combining(c))
    s = s.lower().replace("\xa0", " ")
    s = re.sub(r"\.(md|yaml|epub|pdf|txt)$", "", s, flags=re.I)
    s = re.sub(r"[^a-z0-9 ]", " ", s)
    return re.sub(r"\s+", " ", s).strip()


def kw(s, n=10):
    return [w for w in norm(s).split() if len(w) > 3 and w not in STOP][:n]


def index_disco():
    arquivos = []
    por_palavra = defaultdict(list)
    for f in glob.glob(str(BIB / "**" / "*.md"), recursive=True):
        rel = f.replace(str(BIB) + "/", "")
        if rel.startswith("_"):
            continue
        base = os.path.basename(f)[:-3]
        arquivos.append((f, base))
        for w in set(kw(base, 4)):
            por_palavra[w].append((f, base))
    return arquivos, por_palavra


def match(titulo, arquivos, por_palavra):
    tk = kw(titulo, 10)
    if not tk:
        return None
    cont = defaultdict(int)
    for w in tk:
        for f, base in por_palavra.get(w, []):
            cont[f] += 1
    if cont:
        melhor, score = max(cont.items(), key=lambda x: x[1])
        if score >= max(2, len(tk) - 1):
            return melhor
    for f, base in arquivos:
        bw = set(kw(base, 14))
        if all(w in bw for w in tk):
            return f
    return None


def main():
    arquivos, por_palavra = index_disco()
    print(f"acervo: {len(arquivos)} .md")

    total = 0
    for kbpath in sorted(GLOBAL.glob("kb-*.yaml")):
        txt = kbpath.read_text(encoding="utf-8")
        try:
            d = yaml.safe_load(txt)
        except Exception as e:
            print(f"[YAML INVALIDO] {kbpath.name}")
            continue
        roots = [k for k in d if k != "tags"]
        if not roots:
            continue
        r = d[roots[0]]
        if not isinstance(r, dict) or "materiais" not in r:
            continue

        # 1) resolve o path REAL de cada entrada quebrada
        fixes = []  # (caminho_antigo_literal, caminho_novo_literal)
        seen = set()
        for m in r.get("materiais") or []:
            if not isinstance(m, dict):
                continue
            c = m.get("caminho_md") or ""
            if not c or c in seen:
                continue
            seen.add(c)
            if os.path.exists(c):
                continue
            hit = match(m.get("titulo", ""), arquivos, por_palavra)
            if not hit:
                continue
            novo = "./data/" + str(Path(hit).relative_to(BIB))
            fixes.append((c, novo))

        if not fixes:
            continue

        # 2) reescreve em TEXTO: substitui a linha `caminho_md: <antigo>`
        #    (o valor pode estar truncado no arquivo -> casa por prefixo)
        out = txt
        n = 0
        for antigo, novo in fixes:
            base_antigo = antigo.split("/")[-1]
            # localiza a linha cujo valor comeca com o caminho antigo
            padrao = re.compile(
                r"^(\s*caminho_md:\s*)(\S.*?)(\s*)$",
                re.M)
            def sub(mt):
                global n
                val = mt.group(2).strip().strip("'\"")
                if val == base_antigo or val.startswith(base_antigo[:40]) or base_antigo.startswith(val[:40]):
                    n += 1
                    return f"{mt.group(1)}{novo}"
                return mt.group(0)
            out = padrao.sub(sub, out)
        if n:
            kbpath.write_text(out, encoding="utf-8")
            print(f"[fix] {kbpath.name}: {n}")
            total += n

    print(f"\nTOTAL: {total}")
    # 3) revisao
    bad = 0
    for kbpath in sorted(GLOBAL.glob("kb-*.yaml")):
        try:
            d = yaml.safe_load(kbpath.read_text(encoding="utf-8"))
        except Exception:
            continue
        roots = [k for k in d if k != "tags"]
        if not roots:
            continue
        r = d[roots[0]]
        if not isinstance(r, dict):
            continue
        for m in r.get("materiais") or []:
            if isinstance(m, dict) and m.get("caminho_md") and not os.path.exists(m["caminho_md"]):
                bad += 1
    print(f"caminhos ainda quebrados: {bad}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
