{"content":"#!/usr/bin/env python3
"""
Reparador de caminhos das KBs — v4 (aspas simples + escrita textual).

DIAGNOSTICO DEFINITIVO:
  As linhas `caminho_md:` no YAML BRUTO estao COMPLETAS e corretas.
  O que falha e o PARSE: um valor YAML sem aspas que contem `, ` ou `: `
  (ex.: "... Hachette UK, English - J. I. Packer ...") e lido como MAPA
  (chave -> valor) em vez de string. Resultado: o `caminho_md` volta
  TRUNCADO no primeiro `, ` ou `: `.

Correcao: envolver TODO `caminho_md` em aspas simples. Alem disso, normalizar
o prefixo para `./data/...` e reparar os que apontam pra arquivo inexistente
(renomeados) casando pelo TITULO contra o acervo.

Escrita TEXTUAL (regex), preservando o resto do arquivo byte a byte —
`yaml.dump` nao serve aqui porque re-quebra e re-trunca.
"""
import glob
import os
import re
import unicodedata
from collections import defaultdict
from pathlib import Path

import yaml

ROOT = Path("/home/study-agent")
BIB = ROOT / "data/biblioteca"
GLOBAL = BIB / "global"
STOP = {"de", "da", "do", "the", "a", "o", "and", "e", "of", "para", "com"}


def norm(s):
    s = unicodedata.normalize("NFKD", str(s))
    s = "".join(c for c in s if not unicodedata.combining(c))
    s = s.lower().replace("\xa0", " ")
    s = re.sub(r"\.(md|yaml|epub|pdf|txt)$", "", s, flags=re.I)
    s = re.sub(r"[^a-z0-9 ]", " ", s)
    return re.sub(r"\s+", " ", s).strip()


def kw(s, n=10):
    return [w for w in norm(s).split() if len(w) > 3 and w not in STOP][:n]


def index_disco():
    arquivos = []
    por_palavra = defaultdict(list)
    for f in glob.glob(str(BIB / "**" / "*.md"), recursive=True):
        rel = f.replace(str(BIB) + "/", "")
        if rel.startswith("_"):
            continue
        base = os.path.basename(f)[:-3]
        arquivos.append((f, base))
        for w in set(kw(base, 4)):
            por_palavra[w].append((f, base))
    return arquivos, por_palavra


def match(titulo, arquivos, por_palavra):
    tk = kw(titulo, 10)
    if not tk:
        return None
    cont = defaultdict(int)
    for w in tk:
        for f, base in por_palavra.get(w, []):
            cont[f] += 1
    if cont:
        melhor, score = max(cont.items(), key=lambda x: x[1])
        if score >= max(2, len(tk) - 1):
            return melhor
    for f, base in arquivos:
        bw = set(kw(base, 14))
        if all(w in bw for w in tk):
            return f
    return None


LINHA_PATH = re.compile(r"^(\s*)(caminho_md:\s*)(.*?)\s*$", re.M)


def aspas(valor):
    return "'" + valor.replace("'", "''") + "'"


def main():
    arquivos, por_palavra = index_disco()
    print(f"acervo: {len(arquivos)} .md")

    total_aspas = 0
    total_fix = 0

    for kbpath in sorted(GLOBAL.glob("kb-*.yaml")):
        txt = kbpath.read_text(encoding="utf-8")
        original = txt

        # ---- PASSO 1: aspas + prefixo ./data/ em TODOS os caminho_md ----
        def rep1(mt):
            global total_aspas
            indent, chave, val = mt.group(1), mt.group(2), mt.group(3)
            v = val.strip()
            if not v:
                return mt.group(0)
            if len(v) >= 2 and v[0] == v[-1] and v[0] in "'\"":
                v = v[1:-1]
            v = v.replace("\xa0", " ")
            if v.startswith("data/biblioteca/"):
                v = "./" + v
            elif v.startswith("biblioteca/"):
                v = "./data/" + v
            total_aspas += 1
            return f"{indent}{chave}{apas(v)}"

        txt = LINHA_PATH.sub(rep1, txt)

        # ---- PASSO 2: reparo dos que ainda nao existem ----
        try:
            d = yaml.safe_load(txt)
        except Exception as e:
            print(f"[YAML INVALIDO apos passo1] {kbpath.name}: {str(e)[:60]}")
            kbpath.write_text(txt, encoding="utf-8")
            continue
        roots = [k for k in d if k != "tags"]
        if not roots:
            continue
        r = d[roots[0]]
        if not isinstance(r, dict) or "materiais" not in r:
            kbpath.write_text(txt, encoding="utf-8")
            continue

        # indexa as entradas pelo titulo para saber o path novo
        reparos = {}
        for m in r.get("materiais") or []:
            if not isinstance(m, dict):
                continue
            c = m.get("caminho_md") or ""
            if not c or not isinstance(c, str):
                continue
            if os.path.exists(c):
                continue
            hit = match(m.get("titulo", ""), arquivos, por_palavra)
            if hit:
                reparos[c] = "./data/" + str(Path(hit).relative_to(BIB))

        if reparos:
            def rep2(mt):
                global total_fix
                v = mt.group(3).strip()
                if len(v) >= 2 and v[0] == v[-1] and v[0] in "'\"":
                    v = v[1:-1]
                if v in reparos:
                    total_fix += 1
                    return f"{mt.group(1)}{mt.group(2)}{apas(reparos[v])}"
                return mt.group(0)
            txt = LINHA_PATH.sub(rep2, txt)

        if txt != original:
            kbpath.write_text(txt, encoding="utf-8")
            n_fix = sum(1 for c in reparos if reparos[c])
            print(f"[fix] {kbpath.name}: aspas+prefixo, {n_fix} caminho(s) remapeado(s)")

    print(f"\nvalores com aspas: {total_aspas} | caminhos remapeados: {total_fix}")

    # ---- revisao ----
    bad = []
    tot = 0
    for kbpath in sorted(GLOBAL.glob("kb-*.yaml")):
        try:
            d = yaml.safe_load(kbpath.read_text(encoding="utf-8"))
        except Exception as e:
            bad.append((kbpath.name, f"YAML INVALIDO: {str(e)[:50]}"))
            continue
        roots = [k for k in d if k != "tags"]
        if not roots:
            continue
        r = d[roots[0]]
        if not isinstance(r, dict):
            continue
        for m in r.get("materiais") or []:
            if isinstance(m, dict) and m.get("caminho_md"):
                tot += 1
                if not os.path.exists(m["caminho_md"]):
                    bad.append((kbpath.name, str(m["caminho_md"])[:70]))
    print(f"\nMATERIAIS COM PATH: {tot} | AINDA QUEBRADOS: {len(bad)}")
    for kb, c in bad[:12]:
        print(f"   {kb:<36} {c}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
