{"content":"#!/usr/bin/env python3
"""
CONSTRUTOR DE KBs — reescreve TODAS as KBs do zero, do zero.

Por que reescrever do zero em vez de reparar:
  O acervo herdou 3 defeitos de serializacao YAML que NENHUM reparo pontual
  resolve de forma confiavel:
    D1) `caminho_md:` sem aspas contendo ", " ou ": "  -> lido como MAPA
    D2) `caminho_md:` partido em 2 LINHAS (safe_dump width=80)
    D3) prefixo inconsistente ("data/...", "./data/...", "biblioteca/...")
  Somados a entradas duplicadas e a nomes de arquivo com espaco/nbsp/em-dash.

Aqui o caminho e o inverso: um PARSER de linha a linha, tolerante a qualquer
formatacao, que extrai os pares chave/valor de cada entrada de material; e um
SERIALIZADOR proprio que so emite ASCII puro (aspas simples, caminho curto).
Assim o resultado e SEMPRE valido, independente do estado de entrada.
"""
import glob
import os
import re
import unicodedata
from collections import defaultdict
from pathlib import Path

ROOT = Path("/home/study-agent")
BIB = (ROOT / "data/biblioteca").resolve()
GLOBAL = BIB / "global"
STOP = {"de", "da", "do", "the", "a", "o", "and", "e", "of", "para", "com"}

# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------
def slugify(nome, maxlen=88):
    n = unicodedata.normalize("NFKD", nome)
    n = "".join(c for c in n if not unicodedata.combining(c))
    n = n.replace("\xa0", " ")
    n = re.sub(r"\.(md|yaml|epub|pdf|txt)$", "", n, flags=re.I)
    n = re.sub(r"[^A-Za-z0-9]+", "-", n)
    n = re.sub(r"-{2,}", "-", n).strip("-")
    return (n[:maxlen].rstrip("-") or "material")


def norm(s):
    s = unicodedata.normalize("NFKD", str(s))
    s = "".join(c for c in s if not unicodedata.combining(c))
    s = s.lower().replace("\xa0", " ")
    s = re.sub(r"\.(md|yaml|epub|pdf|txt)$", "", s, flags=re.I)
    s = re.sub(r"[^a-z0-9 ]", " ", s)
    return re.sub(r"\s+", " ", s).strip()


def kw(s, n=10):
    return [w for w in norm(s).split() if len(w) > 3 and w not in STOP][:n]


def kv_split(line):
    """divide 'chave: valor' respeitando aspas"""
    if ":" not in line:
        return None, None
    i = line.index(":")
    k = line[:i].strip()
    v = line[i + 1:].strip()
    if v[:1] in "'\"" and v[-1:] == v[:1] and len(v) >= 2:
        v = v[1:-1]
    return k, v


def index_disco():
    arquivos = []
    por_palavra = defaultdict(list)
    for f in glob.glob(str(BIB / "**" / "*.md"), recursive=True):
        rel = str(Path(f).relative_to(BIB))
        if rel.startswith("_"):
            continue
        base = Path(f).stem
        arquivos.append((str(Path(f).resolve()), base))
        for w in set(kw(base, 4)):
            por_palavra[w].append((str(Path(f).resolve()), base))
    return arquivos, por_palavra


def match(titulo, basename, arquivos, por_palavra):
    for f, base in arquivos:
        if base == basename:
            return f
    tk = kw(titulo, 10)
    if not tk:
        return None
    cont = defaultdict(int)
    for w in tk:
        for f, base in por_palavra.get(w, []):
            cont[f] += 1
    if cont:
        melhor, score = max(cont.items(), key=lambda x: x[1])
        if score >= max(2, len(tk) - 1):
            return melhor
    for f, base in arquivos:
        bw = set(kw(base, 14))
        if all(w in bw for w in tk):
            return f
    nb = norm(basename)
    for cut in (30, 24, 18):
        if len(nb) > cut:
            cands = {f for f, base in arquivos if norm(base).startswith(nb[:cut])}
            if len(cands) == 1:
                return list(cands)[0]
    return None


# ---------------------------------------------------------------------------
# PARSER tolerante: extrai entradas de material de um YAML bagunçado
# ---------------------------------------------------------------------------
def parse_materiais(txt):
    """devolve lista de dicts (titulo, caminho_md, ...)"""
    linhas = txt.split("\n")
    materiais = []
    atual = None
    i = 0
    while i < len(linhas):
        l = linhas[i]
        # novo item da lista
        if re.match(r"^\s*-\s+", l):
            if atual:
                materiais.append(atual)
            atual = {}
            l = re.sub(r"^\s*-\s+", "", l)
        if atual is None:
            i += 1
            continue
        k, v = kv_split(l)
        if k is None:
            i += 1
            continue
        if k == "caminho_md":
            # junta linhas de continuacao
            while (not v.rstrip().endswith((".md", ".yaml", ".txt", ".pdf", ".epub"))
                   and i + 1 < len(linhas)):
                prox = linhas[i + 1]
                pk, _ = kv_split(prox)
                if pk and pk not in ("titulo", "caminho_md"):
                    break
                if re.match(r"^\s*-\s+", prox):
                    break
                v = (v.rstrip() + " " + prox.strip()).strip()
                i += 1
                if v.strip("'\"").rstrip().endswith(".md"):
                    break
        atual[k] = v
        i += 1
    if atual:
        materiais.append(atual)
    return materiais


def parse_cabecalho(txt):
    """extrai tags e os campos de topo do KB (fora da lista materiais)"""
    import yaml
    d = {}
    try:
        d = yaml.safe_load(txt) or {}
    except Exception:
        d = {}
    return d


# ---------------------------------------------------------------------------
# SERIALIZADOR: emite YAML ASCII valido
# ---------------------------------------------------------------------------
def esc(v):
    s = str(v).replace("\xa0", " ")
    s = re.sub(r"\s*\n\s*", " ", s).strip()
    if s == "":
        return "''"
    if re.search(r"[:#\[\]{}&*!|>'\"%@`,]|^[\s-]|[ \t]$", s):
        return "'" + s.replace("'", "''") + "'"
    return s


def serializar(root_key, headers, materiais):
    out = []
    for k, v in headers.items():
        if k == "tags":
            out.append("tags:")
            for t in v:
                out.append(f"  - {esc(t)}")
        elif k == root_key:
            continue
    out.append(f"{root_key}:")
    for k, v in headers.items():
        if k in ("tags", root_key):
            continue
        if isinstance(v, list):
            out.append(f"  {k}:")
            for item in v:
                out.append(f"    - {esc(item)}")
        elif isinstance(v, dict):
            out.append(f"  {k}:")
            for k2, v2 in v.items():
                out.append(f"    {k2}: {esc(v2)}")
        else:
            out.append(f"  {k}: {esc(v)}")
    out.append("  materiais:")
    for m in materiais:
        first = True
        for k, v in m.items():
            if isinstance(v, list):
                sv = "[" + ", ".join(esc(x) for x in v) + "]"
            else:
                sv = esc(v)
            out.append(f"{'    - ' if first else '      '}{k}: {sv}")
            first = False
    return "\n".join(out) + "\n"


# ---------------------------------------------------------------------------
def main():
    arquivos, por_palavra = index_disco()
    print(f"acervo: {len(arquivos)} .md")

    total = 0
    stats = {"keep": 0, "fix": 0, "drop": 0}

    for kbpath in sorted(GLOBAL.glob("kb-*.yaml")):
        txt = kbpath.read_text(encoding="utf-8")
        cab = parse_cabecalho(txt)
        if not isinstance(cab, dict):
            continue
        roots = [k for k in cab if k != "tags"]
        if not roots:
            continue
        root_key = roots[0]
        cabroot = cab[root_key]
        if not isinstance(cabroot, dict):
            continue

        # materiais: tenta primeiro o parse tolerante (pega paths partidos),
        # depois completa com o parse do yaml (pega campos que o grosso leu)
        brutos = parse_materiais(txt)
        try:
            y = __import__("yaml").safe_load(txt)
            ymats = (y.get(root_key) or {}).get("materiais") or []
        except Exception:
            ymats = []
        # combina: para cada entrada do yaml, usa o caminho do parse tolerante
        tol_paths = [m.get("caminho_md", "") for m in brutos if isinstance(m, dict)]
        ymat_list = [m for m in ymats if isinstance(m, dict)]
        if len(ymat_list) != len(tol_paths):
            # usa so o yaml (mais confiável em contagem)
            ymat_list = ymat_list or brutos

        novos = []
        vistos = set()
        for i, m in enumerate(ymat_list):
            c = m.get("caminho_md") or ""
            if not isinstance(c, str):
                c = ""
            c = c.replace("\xa0", " ").strip()
            if i < len(tol_paths) and not c:
                c = tol_paths[i]
            base = Path(c).name if c else ""
            hit = None
            if c:
                cand = ROOT / c.replace("./", "", 1)
                if cand.exists():
                    hit = str(cand.resolve())
            if not hit and base:
                hit = match(m.get("titulo", ""), base[:-3] if base.endswith(".md") else base,
                            arquivos, por_palavra)
            if not hit:
                stats["drop"] += 1
                continue
            rel = Path(hit).resolve().relative_to(BIB)
            novo = "./data/biblioteca/" + str(rel)
