{"content":"#!/usr/bin/env python3
"""
LIMPEZA FINAL das KBs — corrige QUALQUER `caminho_md` partido em 2 linhas,
em qualquer lugar do arquivo (inclusive listas de nivel superior como
`constituicao_estatutos` do kb-ipb-global).

O defeito: o `yaml.safe_dump` antigo (width=80) partia o caminho em 2 linhas.
O YAML parseia a 1a linha como valor e a 2a como lixo (chave solta) -> o lint
acusa "caminho_md não existe".

Solucao: reescrever a entrada em bloco, com o caminho COMPLETO e entre aspas
simples, e o caminho real resolvido contra o disco.
"""
import glob
import os
import re
import unicodedata
from collections import defaultdict
from pathlib import Path

import yaml

ROOT = Path("/home/study-agent").resolve()
BIB = (ROOT / "data/biblioteca").resolve()
GLOBAL = BIB / "global"
STOP = {"de", "da", "do", "the", "a", "o", "and", "e", "of", "para", "com"}


def slugify(nome, maxlen=88):
    n = unicodedata.normalize("NFKD", nome)
    n = "".join(c for c in n if not unicodedata.combining(c))
    n = n.replace("\xa0", " ")
    n = re.sub(r"\.(md|yaml|epub|pdf|txt)$", "", n, flags=re.I)
    n = re.sub(r"[^A-Za-z0-9]+", "-", n)
    n = re.sub(r"-{2,}", "-", n).strip("-")
    return (n[:maxlen].rstrip("-") or "material")


def norm(s):
    s = unicodedata.normalize("NFKD", str(s))
    s = "".join(c for c in s if not unicodedata.combining(c))
    s = s.lower().replace("\xa0", " ")
    s = re.sub(r"\.(md|yaml|epub|pdf|txt)$", "", s, flags=re.I)
    s = re.sub(r"[^a-z0-9 ]", " ", s)
    return re.sub(r"\s+", " ", s).strip()


def kw(s, n=10):
    return [w for w in norm(s).split() if len(w) > 3 and w not in STOP][:n]


def index_disco():
    arquivos = []
    por_palavra = defaultdict(list)
    for f in glob.glob(str(BIB / "**" / "*.md"), recursive=True):
        rel = str(Path(f).relative_to(BIB))
        if rel.startswith("_"):
            continue
        base = Path(f).stem
        arquivos.append((str(Path(f).resolve()), base))
        for w in set(kw(base, 4)):
            por_palavra[w].append((str(Path(f).resolve()), base))
    return arquivos, por_palavra


def match(titulo, basename, arquivos, por_palavra):
    for f, base in arquivos:
        if base == basename:
            return f
    tk = kw(titulo, 10)
    if not tk:
        return None
    cont = defaultdict(int)
    for w in tk:
        for f, base in por_palavra.get(w, []):
            cont[f] += 1
    if cont:
        melhor, score = max(cont.items(), key=lambda x: x[1])
        if score >= max(2, len(tk) - 1):
            return melhor
    for f, base in arquivos:
        bw = set(kw(base, 14))
        if all(w in bw for w in tk):
            return f
    nb = norm(basename)
    for cut in (30, 24, 18):
        if len(nb) > cut:
            cands = {f for f, base in arquivos if norm(base).startswith(nb[:cut])}
            if len(cands) == 1:
                return list(cands)[0]
    return None


# ---------------------------------------------------------------------------
# Reescrita TEXTUAL: junta o caminho partido e resolve contra o disco
# ---------------------------------------------------------------------------
RE_PATH = re.compile(r"^([ \t]*)(caminho_md:[ \t]*)(.*?)([ \t]*)$")


def reescrever_bloco(txt, arquivos, por_palavra, stats):
    """processa o arquivo linha a linha; quando acha `caminho_md:` sem
    aspas, junta a(s) linha(s) de continuacao e resolve o caminho real."""
    linhas = txt.split("\n")
    out = []
    i = 0
    while i < len(linhas):
        l = linhas[i]
        m = RE_PATH.match(l)
        if not m:
            out.append(l)
            i += 1
            continue
        indent, chave, val = m.group(1), m.group(2), m.group(3)
        v = val.strip()
        # ja tem aspas? entao so valida
        tem_aspas = len(v) >= 2 and v[0] == v[-1] and v[0] in "'\""
        if tem_aspas:
            v = v[1:-1]
        # junta continuacao se o valor nao termina em extensao
        if not tem_aspas or not v.lower().endswith((".md", ".yaml", ".txt", ".pdf", ".epub")):
            acc = v
            j = i + 1
            while j < len(linhas) and j - i < 6:
                prox = linhas[j]
                if not prox.strip():
                    break
                if RE_PATH.match(prox):
                    break
                # proxima linha e chave nova?
                km = re.match(r"^\s*([A-Za-z_][A-Za-z0-9_]*):", prox)
                if km and km.group(1) not in ("caminho_md",):
                    break
                if re.match(r"^\s*-\s+", prox):
                    break
                acc = (acc.rstrip() + " " + prox.strip()).strip()
                j += 1
                if acc.lower().endswith((".md", ".yaml", ".txt", ".pdf", ".epub")):
                    break
            v = acc
            i = j - 1
        # normaliza prefixo
        if v.startswith("biblioteca/"):
            v = "./data/" + v
        elif v.startswith("data/") and not v.startswith("./data/"):
            v = "./" + v
        # resolve contra o disco
        novo = v
        cand = ROOT / v.replace("./", "", 1) if v else None
        if cand and cand.exists():
            hp = cand.resolve()
            try:
                novo = "./data/biblioteca/" + str(hp.relative_to(BIB))
            except ValueError:
                novo = "./" + str(hp.relative_to(ROOT))
        else:
            base = Path(v).name if v else ""
            if base:
                hit = match("", base[:-3] if base.endswith(".md") else base, arquivos, por_palavra)
                if hit:
                    hp = Path(hit).resolve()
                    try:
                        novo = "./data/biblioteca/" + str(hp.relative_to(BIB))
                    except ValueError:
                        novo = "./" + str(hp.relative_to(ROOT))
                else:
                    # tenta por titulo: procura a entrada no bloco
                    titulo = ""
                    for k in range(len(out) - 1, max(-1, len(out) - 12), -1):
                        tm = re.match(r"^\s*-?\s*titulo:\s*(.*)$", out[k])
                        if tm:
                            titulo = tm.group(1).strip().strip("'\"")
                            break
                    if titulo:
                        hit = match(titulo, base[:-3] if base.endswith(".md") else base,
                                    arquivos, por_palavra)
                        if hit:
                            hp = Path(hit).resolve()
                            try:
                                novo = "./data/biblioteca/" + str(hp.relative_to(BIB))
                            except ValueError:
                                novo = "./" + str(hp.relative_to(ROOT))
        if novo != v:
            stats["fix"] += 1
        out.append(f"{indent}{chave}'{novo.replace(chr(39), chr(39)*2)}'")
        i += 1
    return "\n".join(out)


def main():
    arquivos, por_palavra = index_disco()
    print(f"acervo: {len(arquivos)} .md")
    stats = {"fix": 0}

    for kbpath in sorted(GLOBAL.glob("kb-*.yaml")):
        txt = kbpath.read_text(encoding="utf-8")
        out = reescrever_bloco(txt, arquivos, por_palavra, stats)
        if out != txt:
            kbpath.write_text(out, encoding="utf-8")
            print(f"[fix] {kbpath.name}")

    print(f"\nlinhas de caminho_md reescritas: {stats['fix']}")

    # ---- revisao + lint interno ----
    bad = []
    tot = 0
    for kbpath in sorted(GLOBAL.glob("kb-*.yaml")):
        try:
            d = yaml.safe_load(kbpath.read_text(encoding="utf-8"))
        except Exception as e:
            bad.append((kbpath.name, f"YAML INVALIDO: {str(e)[:50]}"))
            continue

        def walk(o):
            if isinstance(o, dict):
                yield o
                for v in o.values():
                    yield from walk(v)
            elif isinstance(o, list):
                for v in o:
                    yield from walk(v)

        titles = []
        for o in walk(d):
            if isinstance(o, dict) and "caminho_md" in o:
                c = o["caminho_md"]
                if isinstance(c, str) and c:
                    tot += 1
                    if not (ROOT / c.replace("./", "", 1)).exists():
                        bad.append((kbpath.name, c[:70]))
                    if o.get("titulo"):
                        titles.append(c.strip().lower())
        for t in set(titles):
            if titles.count(t) > 1:
                bad.append((kbpath.name, f"DUPLICATA: {t[:60]}"))

    print(f"MATERIAIS COM PATH: {tot} | PROBLEMAS: {len(bad)}")
    for kb, c in bad[:15]:
        print(f"   {kb:<36} {c}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
